        uint256 accumulated = 0;
        for (uint256 i = 0; i < callCount; i++) {
            address player = address(uint160(uint256(keccak256(abi.encodePacked(i, callCount)))));
            vm.deal(player, 10);
            vm.prank(player);
            try c.play{value: 10}() {
                // call succeeded
